bool RenderingQueue::awake()
{
    m_DefaultFont = construct_font(
        RenderingQueueDefaultFont::BUFFER,
        RenderingQueueDefaultFont::COMPRESSED_SIZE,
        128
    );

    // register default shader here
    m_DefaultShader = construct_shader(
        {
            // Vertex shader
            {
                std::string(
R"(
#version 330 core

// vertex attributes
layout (location = 0) in vec3 a_Position;
layout (location = 1) in vec3 a_Normal;
layout (location = 2) in vec2 a_UV;
layout (location = 3) in vec4 a_Color;

// outputs
out vec3 Normal;
out vec2 UV;
out vec4 Color;

// uniforms
uniform mat4 u_ModelMatrix;
uniform mat4 u_CameraViewMatrix;
uniform mat4 u_ProjectionMatrix;

void main()
{
// setup position
gl_Position = u_ProjectionMatrix * u_CameraViewMatrix * u_ModelMatrix * vec4(a_Position, 1.0);

// setup outputs
Normal = a_Normal;
UV     = a_UV;
Color  = a_Color;
}            
)"),
                RenderingQueueShaderType_::RenderingQueueShaderType_Vertex
            },

            // fragment shader
            {
                std::string(
R"(
#version 330 core

// inputs
in vec2 UV;
in vec4 Color;

//outputs
out vec4 fragColor;

//uniforms
uniform sampler2D u_Texture;

void main()
{
    fragColor = Color * texture(u_Texture, UV);
}
)"),
                RenderingQueueShaderType_::RenderingQueueShaderType_Fragment
                },
        }
    );    

    // create default white pattern texture
    const int     height   = 4;
    const int     width    = 4;
    const int     channels = 4;
    const int     red      = 0;
    const int     green    = 1;
    const int     blue     = 2;
    const int     alpha    = 3;
    unsigned char image[width * height * channels]{};

    for (int y = 0; y < height; y++)
    {
        for (int x = 0; x < width; x++)
        {
            image[channels * (y * width + x) + red  ] = 255;
            image[channels * (y * width + x) + green] = 255;
            image[channels * (y * width + x) + blue ] = 255;
            image[channels * (y * width + x) + alpha] = 255;
        }
    }

    m_DefaultTexture = construct_texture(image, width, height);

    return true;
}

void RenderingQueue::frame_start()
{
}

void RenderingQueue::frame_update()
{
}

void RenderingQueue::frame_render()
{
    // this can be a rendering commands !!!
    glEnable(GL_BLEND);
    glEnable(GL_DEPTH_TEST);
    glEnable(GL_STENCIL_TEST);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT | GL_STENCIL_BUFFER_BIT);

    for (int i = 0; i < (int)m_Commands.size(); ++i)
    {
        // execute renderer command
        auto rendererCommand  = m_Commands[i].RendererCommand;

        if(rendererCommand.has_value())
        {
            if(rendererCommand.value().ClippingBox.has_value())
            {
                auto clippingRect = rendererCommand.value().ClippingBox.value();

                glEnable(GL_SCISSOR_TEST);

                glScissor(
                    (int)clippingRect.Min.x,
                    (int)gs_clamp<float>(application()->get_window_framebuffer_size().y - clippingRect.Max.y, 0, application()->get_window_framebuffer_size().y),
                    (int)clippingRect.width(),
                    (int)clippingRect.height());
            }

            if(rendererCommand.value().ClearColor.has_value())
            {
                gs_vec4f clearColor = rendererCommand.value().ClearColor.value() / 255.f;
                glClearColor(clearColor.x, clearColor.y, clearColor.z, clearColor.w);
            }
        }

        // execute rendering command
        auto renderingCommand = m_Commands[i].RenderingCommand;

        if(renderingCommand.has_value())
        {
            auto mesh               = renderingCommand.value().Mesh;
            auto shader             = renderingCommand.value().Shader;
            auto color              = renderingCommand.value().Texture.Color;
            auto texture            = renderingCommand.value().Texture;
            auto transform          = renderingCommand.value().Transform;
            auto meshRenderingHints = renderingCommand.value().MeshRendererHints;

            begin_use_texture(texture);
            begin_use_shader(shader);

            set_shader_uniform(shader, "u_ModelMatrix", transform);
            set_shader_uniform(shader, "u_CameraViewMatrix", m_CameraViewMatrix);
            set_shader_uniform(shader, "u_ProjectionMatrix", m_ProjectionMatrix);
            set_shader_uniform(shader, "u_Texture", 0);

            begin_use_mesh(mesh, meshRenderingHints);
            
            end_use_texture();
            end_use_shader();
            end_use_mesh();

            destroy_mesh(mesh);
        }
    }

    // clear commands queue
    m_Commands.clear();

    glDisable(GL_BLEND);
    glDisable(GL_DEPTH_TEST);
    glDisable(GL_STENCIL_TEST);
    glDisable(GL_SCISSOR_TEST);
}

